// client/src/components/dashboard/VirtualTryOn.js
import React, { useState, useRef, useEffect } from 'react';
import { Pose } from '@mediapipe/pose';
import { Upload, Sparkles, Loader2 } from 'lucide-react';
import './styles/VirtualTryOn.css';

const VirtualTryOn = () => {
  const [userImg, setUserImg] = useState(null); 
  const [garmentImg, setGarmentImg] = useState(null); 
  const [resultImg, setResultImg] = useState(null);
  const [isProcessing, setIsProcessing] = useState(false);
  
  const poseRef = useRef(null);
  // This ref will store the body landmarks detected by AI
  const resultsRef = useRef(null);

  useEffect(() => {
    // 1. Fetch User Profile Photo from DB
    const fetchUserPhoto = async () => {
      try {
        const token = localStorage.getItem('token');
        const res = await fetch('http://localhost:5000/api/profile', {
          headers: { 'Authorization': `Bearer ${token}` }
        });
        const data = await res.json();
        if (data.fullBodyImage) setUserImg(data.fullBodyImage);
      } catch (err) {
        console.error("Error fetching profile photo:", err);
      }
    };

    // 2. Initialize MediaPipe Pose
    poseRef.current = new Pose({
      locateFile: (file) => `https://cdn.jsdelivr.net/npm/@mediapipe/pose/${file}`,
    });

    poseRef.current.setOptions({
      modelComplexity: 1,
      smoothLandmarks: true,
      minDetectionConfidence: 0.5,
      minTrackingConfidence: 0.5,
    });

    // 3. Set up the Result Listener
    poseRef.current.onResults((results) => {
      console.log("AI Pose Detection Results Received:", results);
      resultsRef.current = results;
    });

    fetchUserPhoto();

    // Cleanup on unmount
    return () => {
      if (poseRef.current) poseRef.current.close();
    };
  }, []);

  const handleGarmentUpload = (e) => {
    const file = e.target.files[0];
    const reader = new FileReader();
    reader.onloadend = () => setGarmentImg(reader.result);
    if (file) reader.readAsDataURL(file);
  };

  const generateTryOn = async () => {
    if (!userImg || !garmentImg) return;
    setIsProcessing(true);
    
    try {
      // 1. Run MediaPipe
      const imgElement = new Image();
      imgElement.src = userImg;
      imgElement.crossOrigin = "anonymous";
      
      await new Promise((resolve) => { imgElement.onload = resolve; });
      await poseRef.current.send({ image: imgElement });

      // 2. Wait for landmarks to be captured
      if (!resultsRef.current || !resultsRef.current.poseLandmarks) {
        throw new Error("Body detection failed. Use a clearer photo.");
      }

      // 3. POST request
      const response = await fetch('http://localhost:5000/api/ai/tryon', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          baseImage: userImg,
          garmentImage: garmentImg,
          landmarks: resultsRef.current.poseLandmarks 
        })
      });

      const data = await response.json();

      if (!response.ok) {
        throw new Error(data.error || "Server failed to process image");
      }

      // SUCCESS
      setResultImg(data.outputUrl);
    } catch (err) {
      console.error("Detailed Error:", err);
      alert("Generation Failed: " + err.message);
    } finally {
      setIsProcessing(false);
    }
  };

  return (
    <div className="vto-layout">
      {/* LEFT: INPUTS */}
      <div className="vto-panel">
        <h3><span className="text-gradient">1. Your Base Model</span></h3>
        <div className="vto-preview-box">
          {userImg ? (
            <img src={userImg} alt="User Model" />
          ) : (
            <p>No model photo found in profile.</p>
          )}
        </div>

        <h3><span className="text-gradient">2. Upload New Garment</span></h3>
        <div className="upload-zone" onClick={() => document.getElementById('garmentInput').click()}>
          {garmentImg ? (
            <img src={garmentImg} alt="Garment" />
          ) : (
            <div className="upload-content">
              <Upload size={40} color="#fb3e8d" />
              <p>Select Clothing Image</p>
            </div>
          )}
          <input 
            type="file" 
            id="garmentInput" 
            hidden 
            accept="image/*"
            onChange={handleGarmentUpload} 
          />
        </div>

        <button 
          className="generate-btn" 
          disabled={!garmentImg || isProcessing || !userImg} 
          onClick={generateTryOn}
        >
          {isProcessing ? (
            <><Loader2 className="spinner" /> AI Processing...</>
          ) : (
            <><Sparkles size={18} /> Generate AI Look</>
          )}
        </button>
      </div>

      {/* RIGHT: OUTPUT */}
      <div className="vto-panel output-panel">
        <h3><span className="text-gradient">AI Virtual Result</span></h3>
        <div className="vto-preview-box result-box">
          {isProcessing && <div className="scanning-bar" />}
          {resultImg ? (
            <img src={resultImg} alt="Generated Result" />
          ) : (
            <div className="placeholder-text">
              {isProcessing ? "Analyzing Body & Fabric..." : "Your AI transformation will appear here"}
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default VirtualTryOn;
